@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()
c = TestClient(app)
print(c.post("/dessert", json={"time_to_cook":1,"num_ingredients":2,"fruit":"apple"}).json())
